 function pressed(k){if(k==='left'||k==='right'||k==='jump'||k==='attack'||k==='throw'||k==='interact')keys[k]=true;}
 function keydown(e){let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!keys[k]){if(k===' '||k==='arrowup'||k==='w')jump();if(k==='j'||k==='x')swing();if(k==='k'||k==='c')throwSkull();if(k==='e')interact();}keys[k]=true}
 function keyup(e){keys[e.key.toLowerCase()]=false}
 window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);
-document.querySelectorAll('.touch').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(k==='jump')jump();else if(k==='attack')swing();else if(k==='throw')throwSkull();else if(k==='interact')interact();else pressed(k)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>{if(k==='left'||k==='right')keys[k]=false}))});
+document.querySelectorAll('.touch').forEach(b=>{let k=b.dataset.key;b.addEventListener('contextmenu',e=>e.preventDefault());b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(k==='jump')jump();else if(k==='attack')swing();else if(k==='throw')throwSkull();else if(k==='interact')interact();else pressed(k)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>{if(k==='left'||k==='right')keys[k]=false}))});
 function jump(){if(!running||dialogState)return;if(player.jumps<2){player.vy=player.jumps===0?-10.4:-9.2;player.jumps++;player.onGround=false;toastTimer=toastTimer;}}
 function swing(){if(!running||player.attack>0||dialogState)return;player.attack=.25;for(let f of foes){if(f.hp>0&&Math.abs(player.x+16-(f.x+f.w/2))<65&&Math.abs(player.y+25-(f.y+f.h/2))<55){f.hp--;f.x+=player.face*18;if(f.hp<=0){player.souls++;toast('ENCANTADO LIBERTO　+1 ALMA')}}}if(boss.active&&!boss.dead&&Math.abs(player.x+16-(boss.x+boss.w/2))<75&&Math.abs(player.y+25-(boss.y+boss.h/2))<70){boss.hp--;boss.x+=player.face*13;if(boss.hp<=0){boss.dead=true;toast('A CUCA FOI VENCIDA!');ui.bossbar.classList.remove('show')}}}
 function throwSkull(){if(!running||player.throwCD>0||dialogState)return;player.throwCD=1.2;player.headless=1.05;projectiles.push({x:player.x+16+player.face*18,y:player.y+13,vx:player.face*8.6,life:.85});}
 function update(dt){if(!running)return;dt=Math.min(.035,dt);if(player.inv>0)player.inv-=dt;if(player.attack>0)player.attack-=dt;if(player.throwCD>0)player.throwCD-=dt;if(player.headless>0)player.headless-=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}
